<template>
	<!--
	  Hasil Cek NIK & No KK (Data Pengajuan) versi portal. Data dari
	  juragan.api.local.ceknik.get_hasil_cek_nik (output="data"); desk memakai
	  template HTML berisi tabel, portal memakai kartu collapsible seperti
	  AydaUnitCards supaya nyaman di layar HP.
	-->
	<div class="space-y-6">
		<div
			v-for="(p, pi) in people"
			:key="p.peran"
			:class="pi ? 'border-t border-ui-line-gray-100 pt-6' : ''"
		>
			<div>
				<!-- Badge hanya bila Blacklist Eksternal, sejajar label Pemohon/Penjamin -->
				<div class="flex items-center justify-between gap-2">
					<p class="text-base font-bold uppercase tracking-wide text-ui-ink-gray-900">
						{{ p.peran }}
					</p>
					<span
						v-if="p.eksternal_dicek && p.blacklist"
						class="shrink-0 rounded-full bg-ui-surface-red-100 px-2.5 py-0.5 text-xs font-semibold text-ui-ink-red-700"
					>
						Blacklist Eksternal
					</span>
				</div>
				<p class="break-words text-base font-semibold text-ui-ink-gray-900">
					{{ p.nama || '—' }}
				</p>
				<p class="text-sm text-ui-ink-gray-500">
					NIK {{ p.nik || '—' }} · No KK {{ p.no_kk || '—' }}
				</p>
			</div>

			<div v-for="grup in p.groups" :key="grup.key" class="mt-4">
				<h4 class="mb-2 text-sm font-semibold text-ui-ink-gray-900">{{ grup.label }}</h4>
				<p v-if="!grup.items.length" class="text-sm text-ui-ink-gray-400">
					{{ grup.empty }}
				</p>
				<div v-else class="space-y-3">
					<div
						v-for="(item, idx) in grup.items"
						:key="item.key"
						class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm"
					>
						<!-- Header kartu (klik untuk buka/tutup) -->
						<button
							type="button"
							class="flex w-full items-center gap-3 px-4 py-3 text-left transition hover:bg-ui-surface-gray-50"
							@click="toggle(item.key)"
						>
							<span
								class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-sm font-bold text-primary"
							>
								{{ idx + 1 }}
							</span>
							<span class="min-w-0 flex-1">
								<span
									class="block truncate text-sm font-semibold text-ui-ink-gray-900"
								>
									{{ item.title || '—' }}
								</span>
								<span class="block truncate text-xs text-ui-ink-gray-400">
									{{ item.subtitle || '—' }}
								</span>
							</span>
							<span
								v-if="item.pill"
								class="shrink-0 rounded-full px-2 py-0.5 text-xs font-semibold"
								:class="statusPillClass(item.pill)"
							>
								{{ item.pill }}
							</span>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform"
								:class="{ 'rotate-180': isOpen(item.key) }"
								fill="none"
								stroke="currentColor"
								stroke-width="2"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="m6 9 6 6 6-6" />
							</svg>
						</button>

						<!-- Body kartu -->
						<div
							v-if="isOpen(item.key)"
							class="space-y-3 border-t border-ui-line-gray-100 px-4 py-4"
						>
							<div v-for="f in item.fields" :key="f.label">
								<p class="mb-1 text-xs font-medium text-ui-ink-gray-500">
									{{ f.label }}
								</p>
								<!-- No Pengajuan → tautan ke detail pengajuan tersebut -->
								<a
									v-if="f.link"
									:href="pengajuanHref(f.link)"
									class="break-words text-sm font-semibold text-primary underline underline-offset-2"
									@click.prevent="openPengajuan(f.link)"
								>
									{{ f.value }}
								</a>
								<p
									v-else
									class="whitespace-pre-line break-words text-sm text-ui-ink-gray-800"
								>
									{{ f.value == null || f.value === '' ? '—' : f.value }}
								</p>
							</div>
						</div>
					</div>
				</div>
			</div>
		</div>

		<!-- NIK/KK dari hasil Core yang tidak cocok dengan pemohon/penjamin -->
		<div v-if="coreLain.items.length" class="border-t border-ui-line-gray-100 pt-6">
			<h4 class="mb-1 text-sm font-semibold text-ui-ink-gray-900">{{ coreLain.label }}</h4>
			<p class="mb-2 text-xs text-ui-ink-gray-500">
				NIK/KK pada hasil ini tidak sama dengan NIK/KK pemohon maupun penjamin di
				pengajuan.
			</p>
			<div class="space-y-3">
				<div
					v-for="item in coreLain.items"
					:key="item.key"
					class="rounded-2xl border border-ui-line-gray-200 bg-ui-surface px-4 py-3 shadow-sm"
				>
					<p class="truncate text-sm font-semibold text-ui-ink-gray-900">
						{{ item.title || '—' }}
					</p>
					<p class="text-xs text-ui-ink-gray-500">
						{{ item.fields.map((f) => f.value || '—').join(' · ') }}
					</p>
				</div>
			</div>
		</div>

	</div>
</template>

<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { statusPillClass } from '../data/dataPengajuanStatus'

const props = defineProps({
	data: { type: Object, required: true },
})

const router = useRouter()

const CORE_LABEL = 'Cek NIK & KK Internal'
const CORE_EMPTY = {
	belum: 'Belum ada hasil dari Cek NIK & KK / tidak ada data ditemukan.',
}

function coreItems(rows, prefix) {
	return rows.map((r, i) => ({
		key: `${prefix}-core-${i}`,
		title: r.nama,
		subtitle: r.no_perjanjian,
		fields: [
			{ label: 'Dicek', value: `${r.jenis === 'NO KK' ? 'KK' : 'NIK'} ${r.nilai || ''}`.trim() },
			{ label: 'No Perjanjian', value: r.no_perjanjian },
			{ label: 'Peran', value: r.peran_kontrak },
			{ label: 'Status Kontrak', value: r.status_kontrak },
			{ label: 'Sumber', value: r.sumber },
		],
	}))
}

// Tiap orang → 2–3 grup kartu (Internal, Eksternal, Appsheet bila ada).
const people = computed(() =>
	(props.data.people || []).map((p) => {
		const groups = [
			{
				key: 'core',
				label: CORE_LABEL,
				empty: CORE_EMPTY[props.data.core_state] || 'Tidak ada data ditemukan.',
				items: coreItems(p.core || [], p.peran),
			},
			{
				key: 'riwayat',
				label: 'Riwayat Pengajuan',
				empty: p.eksternal_dicek
					? 'Belum pernah diajukan sebelumnya.'
					: 'Riwayat pengajuan belum dicek.',
				items: (p.riwayat || []).map((d) => ({
					key: `${p.peran}-dp-${d.name}`,
					title: d.name,
					subtitle: d.nama_lengkap,
					pill: d.status,
					fields: [
						{ label: 'No Pengajuan', value: d.name, link: d.name },
						{ label: 'Tgl Pengajuan', value: formatDateDisplay(d.tanggal_pengajuan) },
						{ label: 'Sebagai', value: d.peran },
						{ label: 'Cabang', value: d.cabang },
						{ label: 'Status', value: d.status },
						{ label: 'Keputusan', value: d.keputusan },
					],
				})),
			},
		]
		if (p.appsheet?.length) {
			groups.push({
				key: 'appsheet',
				label: 'Riwayat Appsheet',
				empty: '',
				items: p.appsheet.map((a, i) => ({
					key: `${p.peran}-as-${i}`,
					title: formatDateDisplay(a.tanggal_pengajuan),
					subtitle: a.cabang,
					fields: [
						{ label: 'Sebagai', value: a.tipe },
						{ label: 'Cabang', value: a.cabang },
						{ label: 'Nopol', value: a.nopol },
						{ label: 'Nilai Pengajuan', value: currencyDisplay(a.nilai_pengajuan) },
						{ label: 'Hasil Analisa CA', value: a.hasil_analisa_ca },
					],
				})),
			})
		}
		return { ...p, groups }
	}),
)

const coreLain = computed(() => ({
	label: `${CORE_LABEL} lainnya`,
	items: coreItems(props.data.core_lain || [], 'lain'),
}))

// ---- Buka/tutup kartu ----
const openSet = ref(new Set())
function isOpen(key) {
	return openSet.value.has(key)
}
function toggle(key) {
	const s = new Set(openSet.value)
	s.has(key) ? s.delete(key) : s.add(key)
	openSet.value = s
}

// Halaman detail tidak memuat ulang sendiri saat hanya parameter route-nya yang
// berganti, jadi buka pengajuan lain dengan muat penuh.
function pengajuanHref(name) {
	return router.resolve({ name: 'DataPengajuanDetail', params: { name } }).href
}
function openPengajuan(name) {
	window.location.assign(pengajuanHref(name))
}

// ---- Format ----
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(Number(v))}`
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
</script>
